// Dedicated Helpdesk/Support Portal Company. The registered suite's original
// Sales beforeEach is preserved but its order/customer facts are not used here.
async function nativeSupportPortalCompany(withPortal=true){
 const fixture=await expenseFixture(),{createSupportTicket,changeSupportTicket,getSupportTicket}=await import('../../../src/server/modules/support/public/support'),portal=await import('../../../src/server/modules/support/public/ticket-portal');
 async function staff(original:typeof fixture.owner,role:'support_manager'|'support_agent'){
  const actor={...original,role,modules:['support'],branchId:null,departmentId:null};
  actor.assignmentId=await fixture.grant(actor,role);return actor;
 }
 const manager=await staff(fixture.manager,'support_manager'),reviewer=await staff(fixture.tie,'support_manager'),agent=await staff(fixture.head,'support_agent');
 const store=packageGrantStore(db,{authorize:async(_tx,companyId)=>{if(companyId!==fixture.company)throw Error('SUPPORT_PORTAL_NATIVE_FIXTURE_COMPANY');return {userId:'isolated-helpdesk-portal-provider'};},obligations:async()=>{throw Error('SUPPORT_PORTAL_NATIVE_FIXTURE_CANNOT_INACTIVATE');}});
 async function purchase(packageId:'support'|'support-portal',state:'active'|'draining'='active'){
  const prior=(await readCompanyPackageGrants(db,fixture.company)).find(row=>row.packageId===packageId);
  return store.apply({expectedVersion:prior?.version??0,idempotencyKey:key(),grant:{companyId:fixture.company,packageId,packageVersion:1,state,startsAt:0,endsAt:null,version:(prior?.version??0)+1,reason:'Only actual Helpdesk and Support Portal native product source',evidence:'test:support-ticket-portal-native'}});
 }
 await purchase('support');if(withPortal)await purchase('support-portal');
 vi.stubEnv('ERPX_SUPPORT_PACKAGE_ENFORCEMENT','enforced');vi.stubEnv('ERPX_COMMERCE_PACKAGE_ENFORCEMENT','enforced');
 const command=key(),body={kind:'general' as const,title:'First Helpdesk-only customer issue',issue:'Private original internal issue details must never be projected to the Portal.'},created=await createSupportTicket(agent,body,command);
 expect(await createSupportTicket(agent,body,command)).toEqual(created);
 const ticketId=String(created.id);expect(await getSupportTicket(manager,ticketId)).toMatchObject({source_kind:'general',order_id:null,customer_id:null,status:'triage',version:1});
 await changeSupportTicket(manager,ticketId,{action:'triage',expectedVersion:1,ownerId:agent.userId,dueDate:new Date(Date.now()+86400000).toISOString().slice(0,10),reason:'Original manager assigns the actual current Support agent'},key());
 await changeSupportTicket(agent,ticketId,{action:'start',expectedVersion:2,reason:'The actual assigned Support agent starts this general issue'},key());
 const identityImage=async()=>({assignments:(await db.prepare('SELECT to_jsonb(a)::text source FROM assignments a WHERE a.company_id=? ORDER BY a.id').bind(fixture.company).all()).results,members:(await db.prepare('SELECT to_jsonb(m)::text source FROM iam_members m WHERE m.company_id=? ORDER BY m.user_id').bind(fixture.company).all()).results});
 const assertOnlyHelpdeskPurchases=async()=>{expect((await readCompanyPackageGrants(db,fixture.company)).map(row=>row.packageId).sort()).toEqual(withPortal?['support','support-portal']:['support']);expect(await db.prepare('SELECT count(*)::int n FROM commerce_orders WHERE company_id=?').bind(fixture.company).first('n')).toBe(0);};
 await assertOnlyHelpdeskPurchases();
 return {fixture,manager,reviewer,agent,ticketId,portal,support:{createSupportTicket,changeSupportTicket,getSupportTicket},purchase,identityImage,assertOnlyHelpdeskPurchases};
}

